<?php
/**
 * authentication_optimized.php
 *
 * Optimized for performance, security, and maintainability.
 * Replaces procedural bulk with a robust class-based approach.
 */

// -------------------------------------------------------------------------
// Configuration
// -------------------------------------------------------------------------
// In a production environment, store these in environment variables.
define('DB_HOST', 'localhost');
define('DB_NAME', 'your_database_name');
define('DB_USER', 'your_database_user');
define('DB_PASS', 'your_database_password');

// -------------------------------------------------------------------------
// Secure Session Initialization
// -------------------------------------------------------------------------
if (session_status() === PHP_SESSION_NONE) {
    // Ensure cookies are sent only over HTTP(S) and are not accessible to JS
    ini_set('session.cookie_httponly', 1);
    ini_set('session.use_only_cookies', 1);
    // Uncomment the next line if your site is exclusively HTTPS
    // ini_set('session.cookie_secure', 1);
    session_start();
