// -------------------------------------------------------------------------
// Authentication Class
// -------------------------------------------------------------------------
class Authentication
{
    private $pdo;

    public function __construct()
    {
        $this->connectDatabase();
    }

    /**
     * Establishes a secure PDO connection.
     */
    private function connectDatabase(): void
    {
        try {
            $dsn = "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4";
            $options = [
                PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES   => false, // Crucial for security
            ];
            $this->pdo = new PDO($dsn, DB_USER, DB_PASS, $options);
        } catch (PDOException $e) {
            // Log error internally, do not expose details to user
            error_log("Database Connection Error: " . $e->getMessage());
            throw new RuntimeException("Service unavailable.");
        }
    }

    /**
     * Registers a new user.
     *
     * @param string $username
     * @param string $password
     * @return bool
     */
    public function register(string $username, string $password): bool
    {
        // Validate inputs
        if (empty($username) || empty($password)) {
            throw new InvalidArgumentException("Username and password are required.");
        }

        // Use strong hashing algorithm (Argon2 or Bcrypt)
        $passwordHash = password_hash($password, PASSWORD_DEFAULT);

        $sql = "INSERT INTO users (username, password) VALUES (:username, :password)";
        $stmt = $this->pdo->prepare($sql);

        try {
            return $stmt->execute(['username' => $username, 'password' => $passwordHash]);
        } catch (PDOException $e) {
            // Handle duplicate entries (assuming unique constraint on username)
            if ($e->getCode() == 23000) {
                throw new RuntimeException("Username already taken.");
            }
            error_log("Registration Error: " . $e->getMessage());
            return false;
        }
    }

    /**
     * Logs in a user.
     *
     * @param string $username
     * @param string $password
     * @return bool
     */
    public function login(string $username, string $password): bool
    {
        if (empty($username) || empty($password)) {
            return false;
        }

        $sql = "SELECT id, password FROM users WHERE username = :username LIMIT 1";
        $stmt = $this->pdo->prepare($sql);
        $stmt->execute(['username' => $username]);
        $user = $stmt->fetch();

        // Verify password and rehash if necessary (future-proofing)
        if ($user && password_verify($password, $user['password'])) {
            if (password_needs_rehash($user['password'], PASSWORD_DEFAULT)) {
                $newHash = password_hash($password, PASSWORD_DEFAULT);
                $this->updatePasswordHash($user['id'], $newHash);
            }

            // Regenerate session ID to prevent Session Fixation attacks
            session_regenerate_id(true);
            $_SESSION['user_id'] = $user['id'];
            $_SESSION['username'] = $username;

            return true;
        }

        return false;
    }

    /**
     * Updates password hash for a user.
     */
    private function updatePasswordHash(int $userId, string $hash): void
    {
        $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
        $stmt->execute(['id' => $userId, 'password' => $hash]);
    }

    /**
     * Checks if the current user is logged in.
     *
     * @return bool
     */
    public function isLoggedIn(): bool
    {
        return isset($_SESSION['user_id']);
    }

    /**
     * Logs out the current user and destroys the session.
     */
    public function logout(): void
    {
        $_SESSION = [];

        // Delete session cookie
        if (ini_get("session.use_cookies")) {
            $params = session_get_cookie_params();
            setcookie(session_name(), '', time() - 42000, $params["path"], $params["domain"], $params["secure"], $params["httponly"]);
        }

        session_destroy();
    }

    /**
     * Gets the current logged-in user's ID.
     *
     * @return int|null
     */
    public function getUserId(): ?int
    {
        return $_SESSION['user_id'] ?? null;
    }
}

